def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            color = None
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                if grid[y][x] > 1:
                    color = grid[y][x]
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if color is not None:
                for y, x in cells:
                    if 0 < y < h - 1 and 0 < x < w - 1 and all(grid[yy][xx] != 0 for yy in range(y - 1, y + 2) for xx in range(x - 1, x + 2)):
                        out[y][x] = color
    return out

